export function createFrontOfficeQaScenarios() {
  return QA_BASE_SCENARIOS.flatMap((baseScenario) =>
    QA_CHANNELS.map((channel) => ({
      ...baseScenario,
      id: `${baseScenario.id}-${channel}`,
      baseScenarioId: baseScenario.id,
      projectId: "ARTHELLO",
      channel,
      forbiddenActions: ALWAYS_FORBIDDEN,
      synthetic: true,
    })),
  );
}
